INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: hard / L4 — Section 755 allocation of 743(b) adjustment between asset classes
(3, 'Partnerships', 'Ridgemont Partners LP has a Section 754 election in effect. Partner Shaw purchases a 25% interest for $400,000. The partnership''s assets include cash of $200,000, accounts receivable of $200,000 (basis $0), equipment of $400,000 (basis $300,000, Section 1245 property), and goodwill of $800,000 (basis $100,000). Shaw''s 25% share of inside basis is $150,000. Under Section 755, evaluate how the $250,000 Section 743(b) adjustment is allocated between the ordinary income and capital gain asset classes.', '["$50,000 to ordinary assets and $200,000 to capital assets", "$125,000 to each class equally", "$250,000 entirely to capital assets (goodwill)", "$75,000 to ordinary assets and $175,000 to capital assets"]'::jsonb, 3, 'Under Section 755, the 743(b) adjustment is allocated between ordinary income assets (receivables, equipment) and capital gain assets (goodwill) based on the difference between the transferee''s share of FMV and share of inside basis within each class. Shaw''s share of ordinary FMV is $150,000 ($600,000 x 25%) vs. inside basis of $75,000, producing a $75,000 ordinary adjustment. Shaw''s share of capital FMV is $200,000 vs. inside basis of $25,000, producing a $175,000 capital adjustment. The total $250,000 is not split equally (Choice B) because Section 755 requires FMV-based allocation to each class.', 'hard', 4),

-- Q2: easy / L1 — Section 708 partnership termination
(3, 'Partnerships', 'Under IRC Section 708(b)(1), when does a partnership terminate for federal tax purposes?', '["When 50% or more of partnership interests are sold within 12 months", "When no part of the partnership''s business continues to be carried on by any of its partners", "When a new partner is admitted who contributes more than 50% of partnership capital", "When the partnership fails to file Form 1065 for two consecutive years"]'::jsonb, 1, 'Under IRC Section 708(b)(1), a partnership terminates only when no part of its business, financial operation, or venture continues to be carried on by any of its partners. The Tax Cuts and Jobs Act of 2017 repealed the technical termination rule that previously applied when 50% or more of interests were sold within 12 months (Choice A). The remaining options describe events that do not trigger termination under current law.', 'easy', 1),

-- Q3: medium / L2 — Partnership holding period for contributed property (Section 1223(2))
(3, 'Partnerships', 'Partner Ellison contributes land she has held for 8 years with a basis of $50,000 and FMV of $200,000 to Birchwood Partners LP on January 15, 2026. The partnership sells the land on March 1, 2026, for $220,000, less than 2 months after the contribution. What is the partnership''s holding period for the contributed land?', '["Less than 2 months, beginning on the contribution date", "More than 8 years, because the partnership tacks Ellison''s holding period", "12 months, measured from the beginning of the partnership''s tax year", "6 months, the default holding period for partnership contributed assets"]'::jsonb, 1, 'Under Section 1223(2), when property is transferred to a partnership under Section 721 with a carryover basis, the partnership tacks the contributing partner''s holding period. Because Ellison held the land for 8 years before contributing it, the partnership''s holding period exceeds 8 years. The gain qualifies for long-term capital gain treatment despite the partnership owning the land less than 2 months. Choice A incorrectly restarts the holding period at the contribution date, which would apply only if the partnership received a FMV basis.', 'medium', 2),

-- Q4: medium / L3 — Section 735 character of gain on distributed inventory sold within 5 years
(3, 'Partnerships', 'Partner Foley receives inventory with a basis of $15,000 and FMV of $25,000 in a current distribution from Pinewood Partners LP on April 1, 2026. On September 15, 2026, Foley sells the inventory to an unrelated buyer for $30,000. Apply Section 735 to determine the character of Foley''s $15,000 gain on the sale.', '["$15,000 capital gain because Foley is not a dealer in inventory", "$10,000 ordinary income and $5,000 capital gain", "$15,000 ordinary income because the sale occurred within 5 years of the distribution", "$15,000 ordinary income only if the partnership was a dealer in the inventory"]'::jsonb, 2, 'Under Section 735(a)(2), gain on the sale of distributed inventory items is treated as ordinary income if sold within 5 years of the distribution date, regardless of the partner''s dealer status. Because Foley sold the inventory approximately 5 months after receiving it, the entire $15,000 gain ($30,000 proceeds minus $15,000 basis) is ordinary income. Choice A incorrectly treats the gain as capital, and Choice D incorrectly conditions ordinary treatment on the partnership''s dealer status rather than the 5-year holding rule.', 'medium', 3),

-- Q5: easy / L1 — Section 752(a) deemed contribution from liability increase
(3, 'Partnerships', 'Under IRC Section 752(a), how is an increase in a partner''s share of partnership liabilities treated for tax purposes?', '["As a deemed cash contribution by the partner to the partnership", "As ordinary income to the partner", "As a nontaxable event with no effect on basis", "As a reduction in the partner''s capital account only"]'::jsonb, 0, 'Under IRC Section 752(a), any increase in a partner''s share of partnership liabilities is treated as a deemed cash contribution by the partner to the partnership. This increases the partner''s outside basis. Conversely, under Section 752(b), a decrease in liability share is a deemed distribution. Choice B is incorrect because liability changes are not income events. Choice C is wrong because the deemed contribution directly increases outside basis.', 'easy', 1),

-- Q6: medium / L2 — Section 709(b) organization costs vs syndication costs
(3, 'Partnerships', 'Timberline Partners LP incurs $8,000 in legal fees for drafting the partnership agreement and $12,000 in printing costs for the offering memorandum used to sell limited partnership interests in 2026. Under Section 709, how are these costs treated?', '["Both amounts are deductible as business expenses in 2026", "The $8,000 is eligible for the Section 709(b) deduction and 180-month amortization; the $12,000 is neither deductible nor amortizable", "Both amounts are capitalized and amortized over 180 months", "The $8,000 is expensed immediately; the $12,000 is amortized over 60 months"]'::jsonb, 1, 'Under Section 709(b), organizational expenses such as legal fees for drafting the partnership agreement qualify for an immediate deduction of up to $5,000 (phased out above $50,000) with the remainder amortized over 180 months. However, syndication costs, which include expenses for selling partnership interests such as printing offering memoranda and brokerage commissions, are neither deductible nor amortizable under Section 709(a). Choice C incorrectly treats syndication costs as amortizable, and Choice A incorrectly treats both as current deductions.', 'medium', 2),

-- Q7: medium / L3 — Partner loan to partnership vs capital contribution effect on basis
(3, 'Partnerships', 'Partner Garrett, a 50% partner in Westfield Partners LP, loans $80,000 to the partnership on a recourse basis at a market interest rate. The other partner, Hansen, has no obligation to repay the debt. Apply the basis rules to determine how Garrett''s $80,000 loan affects each partner''s outside basis.', '["Garrett''s basis increases by $40,000 and Hansen''s basis increases by $40,000", "Garrett''s basis increases by $80,000 and Hansen''s basis is unaffected", "Both partners'' bases increase by $80,000 each", "Neither partner''s basis is affected because loans are not capital contributions"]'::jsonb, 1, 'Under Section 752, a partner''s loan to the partnership creates a partnership liability that must be allocated for basis purposes. Because the loan is recourse and only Garrett bears the economic risk of loss (as the lending partner would be paid back from partnership assets, and Hansen has no repayment obligation), the entire $80,000 liability is allocated to Garrett under Treas. Reg. Section 1.752-2. Garrett''s outside basis increases by $80,000. Choice A incorrectly splits the liability based on profit-sharing ratios, which applies only to nonrecourse liabilities.', 'medium', 3),

-- Q8: easy / L1 — Section 706(a) inclusion year rule
(3, 'Partnerships', 'Under IRC Section 706(a), in which tax year does a partner report their distributive share of partnership income?', '["The partner''s tax year in which the partnership''s tax year ends", "The calendar year in which the income was earned by the partnership", "The partner''s tax year in which the K-1 is received", "The partner''s tax year in which distributions are received"]'::jsonb, 0, 'Under IRC Section 706(a), a partner includes their distributive share of partnership items in the partner''s taxable year within which or with which the partnership''s taxable year ends. This rule prevents indefinite deferral by requiring alignment between partner and partnership reporting. Choice D is incorrect because partnership income is taxed when earned and allocated, not when distributed. Choice C is wrong because K-1 receipt timing is irrelevant to the inclusion year.', 'easy', 1),

-- Q9: medium / L3 — Section 704(c)(1)(C) built-in loss limitation
(3, 'Partnerships', 'Partner Irving contributes equipment with an adjusted basis of $180,000 and FMV of $100,000 to a three-equal-partner partnership. The built-in loss is $80,000. Apply Section 704(c)(1)(C) to determine how the partnership must treat the built-in loss for purposes of allocating depreciation and loss to the non-contributing partners.', '["The non-contributing partners may each claim one-third of the $80,000 built-in loss", "The partnership takes a $100,000 FMV basis in the equipment for purposes of allocating items to non-contributing partners", "The partnership ignores the built-in loss and uses the $180,000 carryover basis for all partners", "The built-in loss is suspended until the contributing partner sells the partnership interest"]'::jsonb, 1, 'Under Section 704(c)(1)(C), when a partner contributes property with a built-in loss (basis exceeds FMV), the partnership''s basis in the property is bifurcated. For purposes of allocating depreciation, gain, or loss to non-contributing partners, the property''s basis is limited to its FMV ($100,000) at contribution. The built-in loss of $80,000 is allocable only to Irving. Choice A incorrectly allows non-contributing partners to share in the pre-contribution loss, which is precisely what Section 704(c)(1)(C) prevents.', 'medium', 3),

-- Q10: easy / L1 — Revocation of Section 754 election
(3, 'Partnerships', 'Once a partnership makes a Section 754 election, what is required to revoke it?', '["Unanimous consent of all partners", "Approval from the IRS", "A majority vote of the partners", "Automatic revocation after 5 years"]'::jsonb, 1, 'Under Treas. Reg. Section 1.754-1(c), a Section 754 election, once made, is effective for all subsequent partnership taxable years and cannot be revoked without the approval (consent) of the IRS District Director. The election is not time-limited (Choice D) and cannot be revoked by partner vote alone (Choices A and C). The IRS will generally grant revocation only if there is a substantial change in the nature of the partnership''s business.', 'easy', 1),

-- Q11: medium / L2 — Section 752(b) deemed distribution from decrease in liability share
(3, 'Partnerships', 'Partner Jennings has a 40% interest in Lakewood Partners LP with an outside basis of $120,000, which includes $60,000 attributable to her share of the partnership''s $150,000 recourse loan. The partnership repays $100,000 of the loan, reducing it to $50,000. Jennings'' new share of the remaining liability is $20,000. What is the effect on Jennings'' outside basis?', '["Basis decreases by $40,000 to $80,000", "Basis decreases by $60,000 to $60,000", "Basis is unchanged because loan repayment is not a distribution", "Basis decreases by $100,000 and Jennings recognizes a $20,000 gain"]'::jsonb, 0, 'Under Section 752(b), a decrease in a partner''s share of partnership liabilities is treated as a deemed cash distribution. Jennings'' share decreased from $60,000 to $20,000, a reduction of $40,000. This deemed distribution reduces her outside basis by $40,000 (from $120,000 to $80,000). Choice B incorrectly uses the full original liability share, and Choice D incorrectly applies the full loan repayment amount rather than Jennings'' share of the decrease.', 'medium', 2),

-- Q12: easy / L1 — Partnership makes elections at entity level
(3, 'Partnerships', 'Which elections are made at the partnership level rather than by individual partners?', '["Accounting method and depreciation method", "Filing status and standard deduction", "Itemized deductions and personal exemptions", "Capital loss carryforward and NOL carryback"]'::jsonb, 0, 'Under IRC Section 703(b), certain elections affecting the computation of taxable income derived from a partnership are made by the partnership rather than by individual partners. These include the choice of accounting method (cash vs. accrual), depreciation method, and inventory method. Choices B and C relate to individual tax attributes that are determined at the partner level. Choice D describes individual carryover provisions not determined at the partnership level.', 'easy', 1),

-- Q13: hard / L3 — Constructive liquidation analysis for economic risk of loss
(3, 'Partnerships', 'Clearview Partners LP has two partners: Monroe (general partner, 60%) and Nash (limited partner, 40%). The partnership has a $500,000 recourse loan from a bank. Under the constructive liquidation analysis in Treas. Reg. Section 1.752-2(b), all partnership assets become worthless and the partnership constructively liquidates. Monroe has an unlimited deficit restoration obligation; Nash has none. Apply the economic risk of loss rules to allocate the $500,000 recourse liability.', '["$300,000 to Monroe and $200,000 to Nash based on profit ratios", "$500,000 to Monroe and $0 to Nash", "$250,000 to each partner equally", "$400,000 to Monroe and $100,000 to Nash based on capital contributions"]'::jsonb, 1, 'Under Treas. Reg. Section 1.752-2(b), recourse liabilities are allocated to the partner(s) who bear the economic risk of loss, determined through a constructive liquidation scenario. If all assets become worthless, the $500,000 loss flows to capital accounts per profit ratios (Monroe $300,000, Nash $200,000). Nash, as a limited partner with no deficit restoration obligation, bears no risk beyond her capital account. Monroe, with an unlimited DRO, bears the entire economic risk of loss because he must restore any deficit. Therefore, the full $500,000 is allocated to Monroe. Choice A incorrectly uses profit ratios, which apply to nonrecourse liabilities.', 'hard', 3),

-- Q14: hard / L4 — Section 761(c) retroactive partnership agreement modifications
(3, 'Partnerships', 'Evergreen Partners LP has three equal partners and a calendar year-end. On February 15, 2027 (before the March 15 filing deadline for 2026), the partners amend the partnership agreement to allocate 50% of 2026 depreciation deductions to Partner Prescott, who joined on January 1, 2026. Evaluate whether this retroactive modification is valid under Section 761(c) and what additional requirement must be met for the allocation to be respected.', '["The amendment is invalid because it was made after the tax year ended", "The amendment is valid under Section 761(c) but the special allocation must also have substantial economic effect under Section 704(b)", "The amendment is automatically valid and needs no additional requirements", "The amendment is valid only if the IRS grants permission for retroactive effect"]'::jsonb, 1, 'Under IRC Section 761(c), any modification to the partnership agreement made before the filing deadline (including extensions) for the partnership return is treated as if it were made during the applicable tax year. Therefore, the February 2027 amendment retroactively applies to 2026. However, Section 761(c) addresses only timing validity; the special allocation of depreciation must independently satisfy the substantial economic effect test under Section 704(b) and Treas. Reg. Section 1.704-1(b)(2). Choice A incorrectly states post-year amendments are per se invalid, ignoring Section 761(c).', 'hard', 4),

-- Q15: easy / L1 — No loss recognized in current distribution
(3, 'Partnerships', 'Under IRC Section 731(a)(2), when can a partner recognize a loss from a partnership distribution?', '["Only in a liquidating distribution consisting solely of money, unrealized receivables, and inventory", "In any distribution where the FMV of property received is less than the partner''s outside basis", "In any current distribution that reduces the partner''s basis to zero", "Whenever distributed property has a FMV below its inside basis"]'::jsonb, 0, 'Under IRC Section 731(a)(2), a loss is recognized to a partner only in a liquidating distribution and only when the distribution consists solely of money, unrealized receivables, and inventory with a value less than the partner''s outside basis. No loss is recognized in a current (nonliquidating) distribution regardless of the values involved. Choice B incorrectly allows loss recognition based on FMV comparisons, and Choice C incorrectly allows loss in current distributions.', 'easy', 1),

-- Q16: easy / L1 — Section 724 contributed unrealized receivable character
(3, 'Partnerships', 'Under IRC Section 724(a), what happens to the character of an unrealized receivable contributed to a partnership by a cash-method partner?', '["It retains its ordinary income character when collected or disposed of by the partnership", "It converts to capital gain property in the partnership''s hands", "It becomes Section 1231 property eligible for long-term capital gain treatment", "Its character depends on the partnership''s accounting method"]'::jsonb, 0, 'Under IRC Section 724(a), any unrealized receivable (as defined in Section 751(c)) contributed by a partner to a partnership retains its ordinary income character in the hands of the partnership. When the partnership collects or disposes of the receivable, the gain or income is ordinary, regardless of the partnership''s own accounting method. This prevents a cash-method partner from shifting ordinary income to capital gain character through a partnership contribution. Choice B is the exact mischaracterization Section 724 was designed to prevent.', 'easy', 1),

-- Q17: easy / L2 — Section 706(d) varying interest rule
(3, 'Partnerships', 'Pinehill Partners LP has two equal partners, Quinn and Russo. On July 1, 2026, Quinn sells half of her interest to a new partner, Torres. For 2026, the partnership earns $240,000 of ordinary income evenly throughout the year. Under Section 706(d), what is Quinn''s allocable share of partnership income for 2026?', '["$120,000 (50% for the full year)", "$60,000 (25% for the full year)", "$90,000 (50% for 6 months plus 25% for 6 months)", "$80,000 (one-third for the full year)"]'::jsonb, 2, 'Under Section 706(d), when a partner''s interest changes during the year, the partner''s share is determined by taking into account the varying interests. For the first half of 2026, Quinn held 50% and is allocated 50% of $120,000 (half-year income) = $60,000. For the second half, Quinn holds 25% and is allocated 25% of $120,000 = $30,000. Total: $90,000. Choice A ignores the mid-year change, and Choice B incorrectly uses the reduced interest for the entire year.', 'easy', 2),

-- Q18: medium / L2 — Distribution of contributed property back to contributing partner (704(c)(1)(B) exception)
(3, 'Partnerships', 'Partner Abbott contributes equipment with a basis of $40,000 and FMV of $110,000 to a three-equal-partner partnership. Two years later, the partnership distributes the same equipment back to Abbott. The equipment now has a FMV of $130,000. Under Section 704(c)(1)(B), what gain must Abbott recognize on this distribution?', '["$70,000, the built-in gain at contribution", "$90,000, the current gain over original basis", "$0, because the property is distributed back to the contributing partner", "$20,000, the post-contribution appreciation"]'::jsonb, 2, 'Under Section 704(c)(1)(B), if contributed property with built-in gain is distributed to a partner other than the contributing partner within 7 years, the contributing partner must recognize the built-in gain. However, when the property is distributed back to the original contributing partner, this rule does not apply. Abbott contributed the equipment and receives it back, so no gain is triggered under Section 704(c)(1)(B). Choice A incorrectly applies the rule even when the contributing partner receives the property back, which defeats the purpose of the provision.', 'medium', 2),

-- Q19: medium / L2 — Section 736 general partnership payments classification
(3, 'Partnerships', 'Partner Crawford retires from a three-person general partnership in which capital is not a material income-producing factor. The partnership pays Crawford $200,000: $130,000 for her share of partnership property and $70,000 above her share of property value. How are the $70,000 excess payments classified under Section 736?', '["Section 736(b) payments treated as a distribution for Crawford''s interest in property", "Section 736(a) payments treated as a distributive share or guaranteed payment", "Return of capital not subject to tax", "Compensation for future services to the partnership"]'::jsonb, 1, 'Under Section 736, payments to a retiring general partner are split into two categories. Section 736(b) payments are for the partner''s interest in partnership property. Section 736(a) payments are amounts exceeding the value of partnership property. In a service partnership (where capital is not a material income-producing factor), payments for unstated goodwill and amounts exceeding property value are Section 736(a) payments, treated as a distributive share or guaranteed payment. The $70,000 excess is therefore a Section 736(a) payment. Choice A incorrectly classifies the excess as a property payment.', 'medium', 2),

-- Q20: easy / L1 — Partnership makes entity-level choice of taxable year
(3, 'Partnerships', 'Which entity is responsible for choosing the partnership''s taxable year under Section 706(b)?', '["The partnership itself", "Each individual partner for their own reporting", "The IRS based on the majority interest partner", "The managing partner independently of the partnership agreement"]'::jsonb, 0, 'Under IRC Section 706(b), the partnership''s taxable year is determined and elected at the partnership level, not by individual partners. The partnership must generally adopt the same taxable year as the majority interest partners (the majority interest taxable year). If no majority exists, the partnership must use the principal partners'' year, or if neither test yields a result, a year that produces the least aggregate deferral. Choice B is incorrect because individual partners do not independently choose the partnership''s year.', 'easy', 1),

-- Q21: medium / L3 — Nonrecourse liability three-tier allocation
(3, 'Partnerships', 'Silverline Partners LP has two equal partners, Drake and Ellis. The partnership takes out a $300,000 nonrecourse loan secured by depreciable equipment. The partnership has $50,000 of partnership minimum gain and $80,000 of Section 704(c) minimum gain attributable to Drake''s contributed property. Apply the three-tier nonrecourse liability allocation rules under Treas. Reg. Section 1.752-3 to determine each partner''s share of the $300,000 liability.', '["Drake $150,000 and Ellis $150,000", "Drake $190,000 and Ellis $110,000", "Drake $300,000 and Ellis $0", "Drake $80,000 and Ellis $220,000"]'::jsonb, 1, 'Under Treas. Reg. Section 1.752-3, nonrecourse liabilities are allocated in three tiers: (1) partnership minimum gain — $50,000 split equally ($25,000 each); (2) Section 704(c) minimum gain — $80,000 allocated entirely to Drake (the contributing partner); (3) remaining $170,000 ($300,000 - $50,000 - $80,000) allocated by profit-sharing ratios (50/50), so $85,000 each. Drake: $25,000 + $80,000 + $85,000 = $190,000. Ellis: $25,000 + $0 + $85,000 = $110,000. Choice A incorrectly ignores the Section 704(c) minimum gain tier and splits the entire liability by profit ratios.', 'medium', 3),

-- Q22: hard / L4 — Traditional with curative allocation method under Section 704(c)
(3, 'Partnerships', 'Partner Hoffman contributes equipment with a basis of $60,000, FMV of $100,000, and 5 years of remaining useful life to an equal two-person partnership. Partner Ives contributes $100,000 cash. Under the traditional method, annual tax depreciation is $12,000 ($60,000 / 5), all allocated to Ives, while book depreciation is $20,000 ($100,000 / 5). The traditional method creates a $8,000 annual ceiling rule disparity. Evaluate how the curative allocation method corrects this shortfall.', '["It allows the partnership to create notional tax items to offset the shortfall", "It allocates other partnership tax items (such as income or gain) away from Ives and to Hoffman to compensate for the depreciation shortfall", "It revalues the contributed property to FMV and recalculates depreciation from the new basis", "It requires Hoffman to make an equalizing cash payment to Ives each year"]'::jsonb, 1, 'Under the traditional method with curative allocations (Treas. Reg. Section 1.704-3(c)), when the ceiling rule prevents full allocation of tax depreciation to the non-contributing partner, the partnership may allocate other actual tax items (such as ordinary income or gain) from Ives to Hoffman to cure the disparity. Unlike the remedial method (Choice A), curative allocations use only actual partnership items, not notional ones. The $8,000 annual shortfall is offset by shifting $8,000 of other partnership income from Ives to Hoffman. Choice C describes a revaluation approach that is not how Section 704(c) methods work.', 'hard', 4),

-- Q23: medium / L2 — Distributive share when partner dies mid-year
(3, 'Partnerships', 'Partner Lambert, a 25% partner in Redstone Partners LP (calendar year), dies on September 30, 2026. Lambert''s estate succeeds to the partnership interest. The partnership earns $400,000 of ordinary income ratably throughout 2026 and uses the proration method under Section 706(d). What amount of partnership income is reported on Lambert''s final individual return?', '["$400,000 (full-year allocable share)", "$100,000 (25% of full-year income)", "$75,000 (25% of income through September 30)", "$0 because income passes to the estate"]'::jsonb, 2, 'Under Section 706(a), a partner includes partnership items in the taxable year that includes the partnership year-end. However, when a partner dies, the partner''s taxable year closes on the date of death. Under Section 706(c)(2)(A), the partnership year does not close with respect to the deceased partner unless the estate/successors elect. Using proration, Lambert is allocated 9/12 of the year''s income (January 1 through September 30). Lambert''s share: 25% x $400,000 x 9/12 = $75,000, reported on the final return. Choice B incorrectly allocates the full year''s share to the deceased partner.', 'medium', 2),

-- Q24: medium / L3 — BBA centralized partnership audit regime imputed underpayment
(3, 'Partnerships', 'Hillcrest Partners LP (three equal partners) is audited under the centralized partnership audit regime (BBA). The IRS determines that the partnership underreported ordinary income by $300,000 for 2024. The partnership does not elect push-out treatment under Section 6226. Apply the BBA rules to determine the imputed underpayment amount at the highest individual tax rate of 37%.', '["$300,000 owed by the partnership", "$111,000 owed by the partnership", "$100,000 owed by each partner individually", "$37,000 owed by each partner individually"]'::jsonb, 1, 'Under the Bipartisan Budget Act (BBA) centralized audit regime (Section 6221-6241), if a partnership does not elect push-out treatment, the partnership itself pays an imputed underpayment calculated at the highest individual tax rate. The imputed underpayment is $300,000 x 37% = $111,000. This amount is assessed and collected at the partnership level in the adjustment year (not the reviewed year). Choice A incorrectly uses the full adjustment amount, and Choice C incorrectly allocates liability to individual partners, which would occur only under push-out treatment.', 'medium', 3),

-- Q25: medium / L3 — Mixed formation aggregate outside basis calculation
(3, 'Partnerships', 'Partner Milton contributes $80,000 cash and equipment with an adjusted basis of $35,000 and FMV of $60,000 to Oakdale Partners LP for a 50% interest. The partnership assumes no liabilities. Apply the formation rules to determine Milton''s aggregate outside basis in the partnership interest.', '["$140,000 (cash plus FMV of equipment)", "$115,000 (cash plus adjusted basis of equipment)", "$80,000 (cash contribution only)", "$95,000 (average of cash and FMV)"]'::jsonb, 1, 'Under Section 721 and Section 722, when a partner contributes both cash and property to a partnership, the partner''s outside basis equals the sum of the cash contributed plus the adjusted basis of each property contributed. Milton''s outside basis is $80,000 (cash) + $35,000 (equipment basis) = $115,000. FMV is irrelevant to basis calculations under Section 722. Choice A incorrectly uses the equipment''s FMV instead of its adjusted basis, which is a common misconception about partnership formation.', 'medium', 3),

-- Q26: medium / L2 — Guaranteed payment deduction timing for partnership
(3, 'Partnerships', 'Ridgevale Partners LP (calendar year, accrual method) accrues a $75,000 guaranteed payment to Partner Norris for management services on December 31, 2026. Norris uses the cash method and does not receive the payment until February 10, 2027. In which year does the partnership deduct the guaranteed payment?', '["2026, the year the payment is determined and accrued", "2027, the year the payment is actually made", "The deduction is split evenly between 2026 and 2027", "The year Norris reports the income on his individual return"]'::jsonb, 0, 'Under IRC Section 707(c) and Treas. Reg. Section 1.707-1(c), guaranteed payments are deductible by the partnership in the partnership''s taxable year in which the payment is properly accrued (i.e., the year it is determined). For an accrual-method partnership, the $75,000 is deducted in 2026 when the obligation becomes fixed and determinable. The partner includes the income under Section 706(a) in the partner''s year that includes the partnership year-end. Choice B incorrectly ties the deduction to the cash payment date rather than the accrual date.', 'medium', 2),

-- Q27: hard / L4 — Section 734(b) mandatory adjustment on distributions
(3, 'Partnerships', 'Evergreen Partners LP has no Section 754 election in effect. The partnership distributes $500,000 cash to retiring Partner Owens in a liquidating distribution. Owens'' outside basis is $200,000, triggering $300,000 of recognized capital gain. The partnership''s remaining inside basis in its assets is $800,000. Evaluate whether a mandatory basis adjustment applies under Section 734(b) and its amount.', '["No adjustment is required because there is no Section 754 election", "A mandatory $300,000 downward adjustment to partnership assets is required", "A mandatory $300,000 upward adjustment to remaining partnership assets is required because the substantial basis reduction threshold is exceeded", "A $200,000 adjustment is made only to the extent of Owens'' original basis"]'::jsonb, 2, 'Under Section 734(d)(1), a mandatory basis adjustment under Section 734(b) is required even without a Section 754 election when there is a substantial basis reduction (exceeding $250,000) resulting from a distribution. Owens recognized $300,000 of gain ($500,000 cash minus $200,000 basis), which exceeds the $250,000 threshold. The partnership must increase the basis of its remaining assets by $300,000 under Section 734(b)(1)(A). Choice A is incorrect because the mandatory adjustment exception overrides the absence of a Section 754 election when the threshold is met.', 'hard', 4),

-- Q28: medium / L2 — Designated partnership representative under BBA
(3, 'Partnerships', 'Under the centralized partnership audit regime enacted by the Bipartisan Budget Act, Cliffside Partners LP must designate a partnership representative. Who may serve in this role, and what authority does the representative have?', '["Only a partner may serve, with authority limited to receiving IRS notices", "Any person with a substantial presence in the United States, with binding authority over all partners for audit proceedings", "Only the tax matters partner designated in the original partnership agreement", "Any partner, but the representative''s decisions require majority partner approval"]'::jsonb, 1, 'Under IRC Section 6223, the partnership representative designated under the BBA need not be a partner; any person (including a non-partner entity or individual) with a substantial presence in the United States may serve. The representative has sole authority to bind the partnership and all partners in IRS audit proceedings without requiring partner consent. This differs from the former tax matters partner regime. Choice A incorrectly limits the role to partners, and Choice D incorrectly requires majority approval, which contradicts the centralized nature of the BBA regime.', 'medium', 2),

-- Q29: medium / L3 — Section 704(c) depreciation allocation ceiling rule
(3, 'Partnerships', 'Partner Rivera contributes a building with a basis of $60,000, FMV of $200,000, and 10 years of remaining useful life to an equal two-person partnership. Partner Santos contributes $200,000 cash. Using the traditional method, the partnership claims $6,000 of annual tax depreciation ($60,000 / 10 years). Book depreciation is $20,000 annually ($200,000 / 10 years). Apply Section 704(c) to determine each partner''s share of the tax depreciation and identify the ceiling rule limitation.', '["Rivera $3,000 and Santos $3,000, split equally", "Rivera $0 and Santos $6,000, with a $4,000 annual ceiling rule shortfall to Santos", "Rivera $0 and Santos $6,000, with no ceiling rule issue", "Rivera $6,000 and Santos $0, because Rivera contributed the property"]'::jsonb, 1, 'Under Section 704(c) using the traditional method, book depreciation of $20,000 is split $10,000 to each partner. Santos (the non-contributing partner) should receive $10,000 of tax depreciation to match her book allocation. However, total tax depreciation is only $6,000, so the ceiling rule caps Santos''s tax allocation at $6,000 (all available tax depreciation), and Rivera receives $0. This creates a $4,000 annual shortfall ($10,000 book minus $6,000 tax) that the traditional method cannot correct. Choice C incorrectly states there is no ceiling rule issue, but the $4,000 gap is precisely the shortfall that curative or remedial methods address.', 'medium', 3),

-- Q30: hard / L4 — Partnership interest not eligible for like-kind exchange
(3, 'Partnerships', 'Partner Wagner holds a 30% interest in Alpine Partners LP, a real estate partnership. Wagner proposes to exchange her partnership interest for a 30% interest in Summit Partners LP, also a real estate partnership, in a transaction she believes qualifies under Section 1031. Both partnerships hold only domestic real property. Evaluate whether this exchange qualifies for like-kind exchange treatment.', '["The exchange qualifies because both partnerships hold real property", "The exchange qualifies if Wagner held her Alpine interest for more than one year", "The exchange does not qualify because Section 1031(a)(2)(D) specifically excludes partnership interests from like-kind exchange treatment", "The exchange qualifies under check-the-box if both entities elect to be disregarded"]'::jsonb, 2, 'Under IRC Section 1031(a)(2)(D), interests in a partnership are specifically excluded from like-kind exchange treatment, regardless of the underlying assets held by the partnerships. Even though both partnerships hold qualifying real property, the exchange of partnership interests themselves is ineligible for Section 1031 nonrecognition. This is a statutory exclusion that cannot be overcome by the nature of partnership assets. Choice A reflects a common misconception that the underlying asset character controls, but the Code expressly excludes partnership interests. Wagner would recognize gain or loss on the exchange under Section 741.', 'hard', 4)
;

COMMIT;
